package az.jeparla.search;

import az.jeparla.common.persistence.CreatedEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.util.Objects;

/**
 * A pair of words that mean the same in search (V11, PLAN 5.3, 5.8): "serqa" and "sırğa",
 * "кольцо" and "üzük". It works in both directions. Admins manage the list (#40); the folded forms
 * are generated by PostgreSQL ({@code jeparla_fold}).
 */
@Entity
@Table(name = "search_synonyms")
public class SearchSynonym extends CreatedEntity {

    @Column(name = "term", nullable = false)
    private String term;

    @Column(name = "synonym", nullable = false)
    private String synonym;

    @Column(name = "term_folded", insertable = false, updatable = false)
    private String termFolded;

    @Column(name = "synonym_folded", insertable = false, updatable = false)
    private String synonymFolded;

    protected SearchSynonym() {
    }

    public SearchSynonym(String term, String synonym) {
        this.term = Objects.requireNonNull(term);
        this.synonym = Objects.requireNonNull(synonym);
    }

    /** Admin edit (#40); the folded forms are generated again by PostgreSQL. */
    public void replace(String term, String synonym) {
        this.term = Objects.requireNonNull(term);
        this.synonym = Objects.requireNonNull(synonym);
    }

    public String getTerm() {
        return term;
    }

    public String getSynonym() {
        return synonym;
    }

    /** {@code jeparla_fold(term)}, read after the row is saved and reloaded. */
    public String getTermFolded() {
        return termFolded;
    }

    /** {@code jeparla_fold(synonym)}, read after the row is saved and reloaded. */
    public String getSynonymFolded() {
        return synonymFolded;
    }
}
